mapper.select:
SELECT o.*, s.name AS scenic_spot_name, u.real_name AS operator_name FROM ticket_order o LEFT JOIN scenic_spot s ON o.scenic_spot_id = s.id LEFT JOIN sys_user u ON o.user_id = u.id WHERE o.deleted = 0
AND o.status = #{status}
AND o.order_no LIKE CONCAT('%', #{orderNo}, '%')
AND o.visitor_name LIKE CONCAT('%', #{visitorName}, '%')
AND o.scenic_spot_id = #{scenicSpotId}
AND o.created_at >= #{startDate}
AND o.created_at <= #{endDate}
ORDER BY o.created_at DESC

SELECT COALESCE(SUM(actual_amount), 0)
FROM ticket_order
WHERE deleted = 0

    AND status = #{status}


    AND DATE(created_at) >= #{startDate}


    AND DATE(created_at) <= #{endDate}

SELECT DATE(created_at) AS date, COUNT(*) AS order_count, COALESCE(SUM(actual_amount), 0) AS total_amount, COALESCE(SUM(CASE WHEN status = 'PAID' OR status = 'USED' THEN actual_amount ELSE 0 END), 0) AS paid_amount FROM ticket_order WHERE deleted = 0
AND DATE(created_at) >= #{startDate}
AND DATE(created_at) <= #{endDate}
GROUP BY DATE(created_at) ORDER BY DATE(created_at)

SELECT tt.name AS ticket_name, tt.category, COALESCE(SUM(oi.quantity), 0) AS total_quantity, COALESCE(SUM(oi.subtotal), 0) AS total_amount FROM ticket_order_item oi INNER JOIN ticket_order o ON oi.order_id = o.id INNER JOIN ticket_type tt ON oi.ticket_type_id = tt.id WHERE o.deleted = 0 AND o.status IN ('PAID', 'USED')
AND DATE(o.created_at) >= #{startDate}
AND DATE(o.created_at) <= #{endDate}
GROUP BY tt.id, tt.name, tt.category ORDER BY total_amount DESC

SELECT s.name AS scenic_name, COUNT(DISTINCT o.id) AS order_count, COALESCE(SUM(o.actual_amount), 0) AS total_amount, COALESCE(SUM(oi.quantity), 0) AS ticket_count FROM ticket_order o INNER JOIN scenic_spot s ON o.scenic_spot_id = s.id LEFT JOIN ticket_order_item oi ON o.id = oi.order_id WHERE o.deleted = 0 AND o.status IN ('PAID', 'USED')
AND DATE(o.created_at) >= #{startDate}
AND DATE(o.created_at) <= #{endDate}
GROUP BY s.id, s.name ORDER BY total_amount DESC
